const debug = @import("debug.zig");
const multiboot = @import("multiboot.zig");

// Variables generated by the linker.
extern var bss_start: u8;
extern var bss_end: u8;
extern var stack: u8;

// Multiboot v1 header, must be within the first 8192 bytes of the ELF file.
// Placed in its own section at the beginning of the linker script's layout.
export const header: [3]u32 align(4) linksection(".multiboot") = .{
    // magic
    multiboot.MULTIBOOT_MAGIC,
    // flags
    0,
    // checksum, -% forces unsigned wrap around subtraction.
    -%@as(u32, multiboot.MULTIBOOT_MAGIC),
};

// Multiboot v1 entry point.
// Set up the stack, then call the Zig kernel entry using the C ABI.
// The EBX register holds the multiboot information structure pointer and will
// be passed as the only argument to startKernel.
export fn _start() callconv(.naked) noreturn {
    asm volatile (
        \\movl $stack, %%esp
        \\cld
        \\sub $12, %%esp
        \\push %%ebx
        \\call startKernel
    );
}

export fn startKernel(info: *multiboot.mb_info) noreturn {
    // clear the BSS section
    const bss: [*]u8 = @ptrCast(&bss_start);
    const bss_len = @intFromPtr(&bss_end) - @intFromPtr(&bss_start);
    @memset(bss[0..bss_len], 0);

    debug.writeString("Hello World!!\n");

    if (info.flags > 0) {
        debug.writeString("Multiboot information available.");
    }

    // The world is your oyster from here...

    while (true) {
        asm volatile ("hlt");
    }
}
